#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long powMod(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long computeResult(long long n, int x, long long even, long long odd, unordered_map<long long, long long>& cache0, unordered_map<long long, long long>& cache1) {
    if (x == 0) {
        if (cache0.count(n)) return cache0[n];
        if (n == 1) return even % MOD;
        if (n == 2) return ((even % MOD) * (even % MOD) + (odd % MOD) * (odd % MOD)) % MOD;
        long long a = computeResult(n / 2, 0, even, odd, cache0, cache1);
        long long b = computeResult(n - n / 2, 0, even, odd, cache0, cache1);
        long long c = computeResult(n / 2, 1, even, odd, cache0, cache1);
        long long d = computeResult(n - n / 2, 1, even, odd, cache0, cache1);
        long long res = (a * b + c * d) % MOD;
        cache0[n] = res;
        return res;
    } else {
        if (cache1.count(n)) return cache1[n];
        if (n == 1) return odd % MOD;
        if (n == 2) return ((even % MOD) * (odd % MOD) + (odd % MOD) * (even % MOD)) % MOD;
        long long a = computeResult(n / 2, 0, even, odd, cache0, cache1);
        long long b = computeResult(n - n / 2, 1, even, odd, cache0, cache1);
        long long c = computeResult(n / 2, 1, even, odd, cache0, cache1);
        long long d = computeResult(n - n / 2, 0, even, odd, cache0, cache1);
        long long res = (a * b + c * d) % MOD;
        cache1[n] = res;
        return res;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    stringstream ss(line);
    long long n, m, left, right;
    ss >> n >> m >> left >> right;

    long long totalCells = n * m;

    if (totalCells % 2 == 0) {
        long long span = right - left + 1;
        long long evenCount = span / 2;
        if (span % 2 == 0 && left % 2 == 0) {
            evenCount++;
        }
        long long oddCount = span - evenCount;

        unordered_map<long long, long long> cache0, cache1;
        cout << computeResult(totalCells, 0, evenCount, oddCount, cache0, cache1) << "\n";
    } else {
        long long span = right - left + 1;
        long long base = span % MOD;
        cout << powMod(base, totalCells) << "\n";
    }
    return 0;
}

